from collections import Counter

def transform(grid):
    colors = set(value for row in grid for value in row)
    if len(colors) != 2:
        raise ValueError("expected a two-color grid")
    low, high = sorted(colors)
    # When color 1 is present, the examples map it to 0 and the other color to 1.
    # For the demonstrated pairs among colors 5-8, map the lower color to the higher,
    # and the higher color to 0.
    if low == 1:
        mapping = {low: 0, high: 1}
    else:
        mapping = {low: high, high: 0}
    return [[mapping[value] for value in row] for row in grid]

